import Foundation

/// The app-level user ID Lens stamps as `u` — one value shared by every
/// handle and namespace, generated by Lens on first report assembly; there is
/// no API to supply one. Persisted in UserDefaults so it survives app
/// restarts.
internal enum UserIdRuntime {
    private static let storageKey = "com.dolby.optiview.lens.u"
    // UserDefaults is writable by anything in the app; only a value shaped
    // like our own v4 UUIDs is trusted — anything else is replaced.
    private static let uuidShape =
        "^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"
    private static let lock = NSLock()
    private nonisolated(unsafe) static var current: String?

    static func currentUserId() -> String {
        lock.lock()
        defer { lock.unlock() }
        if let value = override { return value }
        if let value = current { return value }
        let stored = UserDefaults.standard.string(forKey: storageKey)
            .flatMap { $0.range(of: uuidShape, options: .regularExpression) != nil ? $0 : nil }
        let value = stored ?? UUID().uuidString.lowercased()
        current = value
        UserDefaults.standard.set(value, forKey: storageKey)
        return value
    }

    /// Consent revoked: the ID is identifying, so it is deleted — a later grant starts fresh.
    static func clear() {
        lock.lock()
        defer { lock.unlock() }
        current = nil
        UserDefaults.standard.removeObject(forKey: storageKey)
    }

    // --- Test seams — not part of the production path ---

    nonisolated(unsafe) static var override: String?

    static func resetForTesting() {
        lock.lock()
        defer { lock.unlock() }
        current = nil
        override = nil
        UserDefaults.standard.removeObject(forKey: storageKey)
    }
}
